const mentalHealthConditions = data.mentalHealthConditions || {};
const gastrointestinalIssues = data.gastrointestinalIssues || {};
const diagnosedConditions = data.diagnosedConditions || {};
const lifestyle = data.lifestyle || {};
const confirmation = data.confirmation;

// Check if the user has answered any relevant fields ---
const ageIneligible = age === false;
const bmiIneligible = bmiAnswered && bmi <= 24.9;
const pregnancyStatusIneligible = [
  "pregnant",
  "breastfeeding",
  "possiblyOrTrying"
  ].includes(pregnancyStatus);
const medicalConditionsIneligible = Object.keys(medicalConditions)
  .some(key => key !== 'none' && medicalConditions[key] === true);
const mentalHealthConditionsIneligible = Object.keys(mentalHealthConditions)
  .some(key => key !== 'none' && mentalHealthConditions[key] === true);
const gastrointestinalIssuesIneligible = [
  'gallbladderRemoval',
  'gastroparesis',
  'bowelObstructionHistory',
  'inflammatoryBowelDisease'
  ].some(key => gastrointestinalIssues[key] === true);
const diagnosedConditionsIneligible = [
  'activeCancerTreatment',
  'uncontrolledHypertension',
  'recentHeartAttack',
  'recentStrokeOrTia',
  'heartFailure',
  'heartRhythmDisorder',
  'organTransplant',
  'onDialysis',
  'liverCirrhosisOrFailure',
  'chronicKidneyDiseaseStage4Or5',
  'seizureOrEpilepsy'
  ].some(key => diagnosedConditions[key] === true);
const lifestyleIneligible =
  lifestyle.unprescribedDrugUse === true;
const confirmationIneligible =
  confirmation === 'noIDoNotConfirm';

// Flag indicating if the form has enough answers to evaluate eligibility
const isIneligible = 
    ageIneligible ||
    bmiIneligible ||
    pregnancyStatusIneligible ||
    medicalConditionsIneligible ||
    mentalHealthConditionsIneligible ||
    gastrointestinalIssuesIneligible ||
    diagnosedConditionsIneligible ||
    lifestyleIneligible ||
    confirmationIneligible;

const groupAnswered = obj =>
  Object.values(obj).some(v => v === true);

const hasAnyAnswer =
  age !== undefined ||
  bmiAnswered ||
  pregnancyStatus !== undefined ||
  groupAnswered(medicalConditions) ||
  groupAnswered(mentalHealthConditions) ||
  groupAnswered(gastrointestinalIssues) ||
  groupAnswered(diagnosedConditions) ||
  groupAnswered(lifestyle) ||
  confirmation !== undefined;

  // Set the final value ---
if(isIneligible){
    value = false;
} else if(hasAnyAnswer) {
    value = true;
} else {
    value = null;
}

