components.calculateValue:
let bmi = null;

// Read input values
const unit = data.measurementUnit; // 'metric' or 'imperial'
const height = Number(data.height);
const weight = Number(data.weight);

// Ensure valid inputs
if (height > 0 && weight > 0) {

  // METRIC SYSTEM
  // height: centimeters (cm)
  // weight: kilograms (kg)
  if (unit === 'metric') {
    const heightInMeters = height / 100; // convert cm to meters
    bmi = weight / (heightInMeters * heightInMeters);
  }

  // IMPERIAL SYSTEM
  // height: inches (in)
  // weight: pounds (lb)
  if (unit === 'imperial') {
    bmi = 703 * (weight / (height * height));
  }
}

// Round to 1 decimal
if (bmi !== null && isFinite(bmi)) {
  bmi = Math.round(bmi * 10) / 10;
} else {
  bmi = null;
}

value = bmi;

const conditions = { ...value };

// Is 'none' selected?
const noneSelected = conditions.none === true;

// Are any other options selected?
const otherSelected = Object.keys(conditions)
  .some(key => key !== 'none' && conditions[key] === true);

// If 'none' is selected, it wins → clear others
if (noneSelected) {
  Object.keys(conditions).forEach(key => {
    if (key !== 'none') {
      conditions[key] = false;
    }
  });
}

// If another option is selected, it wins → clear none
if (!noneSelected && otherSelected) {
  conditions.none = false;
}

return conditions;

